import assert from 'node:assert/strict'
import { Buffer } from 'node:buffer'
import { before, describe, it } from 'node:test'
import { Explode } from '../../src/simple/Explode.ts'
import { Implode } from '../../src/simple/Implode.ts'
import { assertTestFilesFolderExists, measure, readFixture } from '../helpers.ts'

/**
 * Creates bytes that the compressor can not find repetitions in, so every byte becomes a literal.
 *
 * @param size The number of the generated bytes.
 * @returns A deterministic pseudo random buffer.
 */
function createIncompressibleData(size: number): Buffer {
  const data = Buffer.alloc(size)
  let state = 0x12_34_56_78

  for (let i = 0; i < size; i++) {
    state = state ^ (state << 13)
    state = state ^ (state >>> 17)
    state = state ^ (state << 5)
    data[i] = state & 0xff
  }

  return data
}

void describe('simple/Implode', () => {
  before(async () => {
    await assertTestFilesFolderExists()

    const unpackedFile = await readFixture('level1.llf.unpacked')

    await measure('⏱ simple/Implode compressed level1.llf.unpacked', () => {
      const instance = new Implode(unpackedFile.buffer, 'binary', 'large')
      instance.getResult()
    })
  })

  void it('can compress binary files', async () => {
    const unpackedFile = await readFixture('level1.llf.unpacked')

    const instance = new Implode(unpackedFile.buffer, 'binary', 'large')
    const packed = instance.getResult()

    const explode = new Explode(packed)
    const unpacked = explode.getResult()

    assert.ok(unpackedFile.equals(new Uint8Array(unpacked)), 'the compressed and decompressed data should match')
  })

  void it('makes the file smaller and actually compress the data, not just encode it', async () => {
    const unpackedFile = await readFixture('level1.llf.unpacked')

    const instance = new Implode(unpackedFile.buffer, 'binary', 'large')
    const packed = instance.getResult()

    assert.ok(packed.byteLength < unpackedFile.byteLength, 'the compressed data should be smaller than the original')
  })

  // a stream of pure literals is what the incompressible input produces, and it has to survive the
  // round trip just like a compressed one
  void it('can compress data that has no repetitions and unpack it back', () => {
    const data = createIncompressibleData(0x1_00)

    const instance = new Implode(data, 'binary', 'large')
    const compressed = instance.getResult()

    const explode = new Explode(compressed)
    const unpacked = explode.getResult()

    assert.ok(Buffer.from(unpacked).equals(data), 'the round trip should keep the bytes that have no repetition')
  })

  // the first two bytes are always literals, so the encoder has to handle the inputs that are shorter
  // than that without losing them
  void it('can compress inputs that are shorter than the two leading literals', () => {
    const matches: boolean[] = []

    for (const size of [0, 1, 2, 3]) {
      const data = Buffer.from([0x0b, 0x30, 0x9f].slice(0, size))

      const instance = new Implode(data, 'binary', 'large')
      const compressed = instance.getResult()

      const explode = new Explode(compressed)
      const unpacked = explode.getResult()

      matches.push(Buffer.from(unpacked).equals(data))
    }

    assert.deepEqual(matches, [true, true, true, true], 'every short input should survive the round trip')
  })

  void it('can compress the same data consistently over and over again when called repeatedly', () => {
    const matches: boolean[] = []

    for (let i = 0; i < 4; i++) {
      const data = Buffer.from('The quick brown fox jumps over the lazy dog. '.repeat(40))

      const implodeInstance = new Implode(data, 'binary', 'large')
      const compressed = implodeInstance.getResult()

      const explode = new Explode(compressed)
      const decompressed = explode.getResult()

      matches.push(Buffer.from(decompressed).equals(data))
    }

    assert.deepEqual(matches, [true, true, true, true], 'every repeated round trip should be stable')
  })
})
